const RABBANA_DUAS = [
  {"id":"rabbana-2-127","n":1,"surah":2,"ayah":127,"part":"","arabic":"رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ","fr":"Notre Seigneur, accepte ceci de notre part. Tu es Celui qui entend et qui sait tout.","en":"Our Lord, accept this from us. You are the All-Hearing, the All-Knowing."},
  {"id":"rabbana-2-128","n":2,"surah":2,"ayah":128,"part":"","arabic":"رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةًۭ مُّسْلِمَةًۭ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","fr":"Notre Seigneur, fais de nous deux des soumis à Toi, et de notre descendance une communauté soumise à Toi. Montre-nous nos rites et reviens vers nous. Tu es Celui qui accepte le repentir, le Miséricordieux.","en":"Our Lord, make us submissive to You, and from our descendants a community submissive to You. Show us our rites and accept our repentance. You are the Accepter of repentance, the Merciful."},
  {"id":"rabbana-2-129","n":3,"surah":2,"ayah":129,"part":"","arabic":"رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fr":"Notre Seigneur, envoie parmi eux un messager issu d’eux, qui leur récite Tes versets, leur enseigne le Livre et la sagesse et les purifie. Tu es le Puissant, le Sage.","en":"Our Lord, send among them a messenger from themselves who will recite Your verses to them, teach them the Book and wisdom, and purify them. You are the Almighty, the Wise."},
  {"id":"rabbana-2-201","n":4,"surah":2,"ayah":201,"part":"","arabic":"رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ حَسَنَةًۭ وَقِنَا عَذَابَ ٱلنَّارِ","fr":"Notre Seigneur, accorde-nous une belle part ici-bas et une belle part dans l’au-delà, et protège-nous du châtiment du Feu.","en":"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."},
  {"id":"rabbana-2-250","n":5,"surah":2,"ayah":250,"part":"","arabic":"رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ","fr":"Notre Seigneur, déverse sur nous la patience, affermis nos pas et donne-nous la victoire sur les gens qui ne croient pas.","en":"Our Lord, pour out patience upon us, make our feet firm and give us victory over the disbelieving people."},
  {"id":"rabbana-2-286-1","n":6,"surah":2,"ayah":286,"part":"1/3","arabic":"رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا","fr":"Notre Seigneur, ne nous tiens pas rigueur si nous avons oublié ou commis une erreur.","en":"Our Lord, do not hold us to account if we forget or make a mistake."},
  {"id":"rabbana-2-286-2","n":7,"surah":2,"ayah":286,"part":"2/3","arabic":"رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًۭا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا","fr":"Notre Seigneur, ne nous charge pas d’un fardeau comme celui dont Tu as chargé ceux d’avant nous.","en":"Our Lord, do not lay on us a burden like the one You laid on those before us."},
  {"id":"rabbana-2-286-3","n":8,"surah":2,"ayah":286,"part":"3/3","arabic":"رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ","fr":"Notre Seigneur, ne nous impose pas ce que nous ne pouvons supporter. Efface nos fautes, pardonne-nous et fais-nous miséricorde. Tu es notre Protecteur : donne-nous la victoire sur les gens qui ne croient pas.","en":"Our Lord, do not burden us with more than we can bear. Pardon us, forgive us and have mercy on us. You are our Protector: give us victory over the disbelieving people."},
  {"id":"rabbana-3-8","n":9,"surah":3,"ayah":8,"part":"","arabic":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ","fr":"Notre Seigneur, ne laisse pas dévier nos cœurs après que Tu nous as guidés, et accorde-nous une miséricorde de Ta part. Tu es Celui qui donne sans cesse.","en":"Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. You are the Ever-Bestowing."},
  {"id":"rabbana-3-9","n":10,"surah":3,"ayah":9,"part":"","arabic":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ","fr":"Notre Seigneur, Tu rassembleras les gens pour un jour sur lequel il n’y a aucun doute. Allah ne manque pas à Sa promesse.","en":"Our Lord, You will gather the people for a Day about which there is no doubt. Allah does not break His promise."},
  {"id":"rabbana-3-16","n":11,"surah":3,"ayah":16,"part":"","arabic":"رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","fr":"Notre Seigneur, nous avons cru : pardonne-nous nos péchés et protège-nous du châtiment du Feu.","en":"Our Lord, we have believed: forgive us our sins and protect us from the punishment of the Fire."},
  {"id":"rabbana-3-53","n":12,"surah":3,"ayah":53,"part":"","arabic":"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ","fr":"Notre Seigneur, nous avons cru à ce que Tu as révélé et nous avons suivi le Messager : inscris-nous parmi ceux qui témoignent.","en":"Our Lord, we have believed in what You revealed and followed the Messenger: write us among those who bear witness."},
  {"id":"rabbana-3-147","n":13,"surah":3,"ayah":147,"part":"","arabic":"رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ","fr":"Notre Seigneur, pardonne-nous nos péchés et nos excès dans notre affaire, affermis nos pas et donne-nous la victoire sur les gens qui ne croient pas.","en":"Our Lord, forgive us our sins and our excesses in our affairs, make our feet firm and give us victory over the disbelieving people."},
  {"id":"rabbana-3-191","n":14,"surah":3,"ayah":191,"part":"","arabic":"رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًۭا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","fr":"Notre Seigneur, Tu n’as pas créé tout cela en vain. Gloire à Toi ! Protège-nous du châtiment du Feu.","en":"Our Lord, You did not create this in vain. Glory be to You! Protect us from the punishment of the Fire."},
  {"id":"rabbana-3-192","n":15,"surah":3,"ayah":192,"part":"","arabic":"رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ","fr":"Notre Seigneur, celui que Tu fais entrer dans le Feu, Tu l’as couvert de honte, et les injustes n’auront aucun secoureur.","en":"Our Lord, whoever You admit to the Fire, You have disgraced him, and the wrongdoers will have no helpers."},
  {"id":"rabbana-3-193","n":16,"surah":3,"ayah":193,"part":"","arabic":"رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ","fr":"Notre Seigneur, nous avons entendu un appelant qui appelait à la foi : « Croyez en votre Seigneur ! », et nous avons cru. Notre Seigneur, pardonne-nous nos péchés, efface nos mauvaises actions et fais-nous mourir avec les gens de bien.","en":"Our Lord, we heard a caller calling to faith: “Believe in your Lord!”, and we believed. Our Lord, forgive us our sins, remove our misdeeds and take our souls with the righteous."},
  {"id":"rabbana-3-194","n":17,"surah":3,"ayah":194,"part":"","arabic":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ","fr":"Notre Seigneur, donne-nous ce que Tu nous as promis par Tes messagers et ne nous couvre pas de honte le Jour de la Résurrection. Tu ne manques jamais à Ta promesse.","en":"Our Lord, grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. You never break Your promise."},
  {"id":"rabbana-4-75","n":18,"surah":4,"ayah":75,"part":"","arabic":"رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّۭا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","fr":"Notre Seigneur, fais-nous sortir de cette cité dont les habitants sont injustes, et donne-nous de Ta part un protecteur, donne-nous de Ta part un secoureur.","en":"Our Lord, take us out of this town whose people are oppressors, and appoint for us from Yourself a protector, and appoint for us from Yourself a helper."},
  {"id":"rabbana-5-83","n":19,"surah":5,"ayah":83,"part":"","arabic":"رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ","fr":"Notre Seigneur, nous avons cru : inscris-nous parmi ceux qui témoignent.","en":"Our Lord, we have believed: write us among those who bear witness."},
  {"id":"rabbana-5-114","n":20,"surah":5,"ayah":114,"part":"","arabic":"ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًۭا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةًۭ مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ","fr":"Ô Allah, notre Seigneur, fais descendre du ciel sur nous une table servie, qui sera une fête pour nous, pour les premiers comme pour les derniers d’entre nous, et un signe de Ta part. Pourvois à notre subsistance : Tu es le meilleur des pourvoyeurs.","en":"O Allah, our Lord, send down to us a table spread from heaven, to be a festival for us, for the first of us and the last of us, and a sign from You. Provide for us: You are the best of providers."},
  {"id":"rabbana-7-23","n":21,"surah":7,"ayah":23,"part":"","arabic":"رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ","fr":"Notre Seigneur, nous nous sommes fait du tort à nous-mêmes. Si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons certes parmi les perdants.","en":"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy on us, we will surely be among the losers."},
  {"id":"rabbana-7-47","n":22,"surah":7,"ayah":47,"part":"","arabic":"رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ","fr":"Notre Seigneur, ne nous place pas avec les gens injustes.","en":"Our Lord, do not place us with the wrongdoing people."},
  {"id":"rabbana-7-89","n":23,"surah":7,"ayah":89,"part":"","arabic":"رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ","fr":"Notre Seigneur, tranche entre nous et notre peuple par la vérité ; Tu es le meilleur de ceux qui tranchent.","en":"Our Lord, decide between us and our people in truth; You are the best of those who decide."},
  {"id":"rabbana-7-126","n":24,"surah":7,"ayah":126,"part":"","arabic":"رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَتَوَفَّنَا مُسْلِمِينَ","fr":"Notre Seigneur, déverse sur nous la patience et fais-nous mourir en musulmans.","en":"Our Lord, pour out patience upon us and take our souls as Muslims."},
  {"id":"rabbana-10-85","n":25,"surah":10,"ayah":85,"part":"","arabic":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلْقَوْمِ ٱلظَّٰلِمِينَ","fr":"Notre Seigneur, ne fais pas de nous une épreuve pour les gens injustes.","en":"Our Lord, do not make us a trial for the wrongdoing people."},
  {"id":"rabbana-14-37","n":26,"surah":14,"ayah":37,"part":"","arabic":"رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةًۭ مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ","fr":"Notre Seigneur, j’ai établi une partie de ma descendance dans une vallée sans culture, près de Ta Maison sacrée. Notre Seigneur, afin qu’ils accomplissent la prière, fais que les cœurs de certains hommes penchent vers eux et accorde-leur des fruits comme nourriture, afin qu’ils soient reconnaissants.","en":"Our Lord, I have settled some of my descendants in a barren valley near Your Sacred House. Our Lord, that they may establish prayer, make the hearts of some people incline toward them and provide them with fruits, so that they may be grateful."},
  {"id":"rabbana-14-38","n":27,"surah":14,"ayah":38,"part":"","arabic":"رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ","fr":"Notre Seigneur, Tu sais ce que nous cachons et ce que nous montrons. Rien n’échappe à Allah, ni sur terre ni dans le ciel.","en":"Our Lord, You know what we conceal and what we reveal. Nothing is hidden from Allah, on earth or in the heavens."},
  {"id":"rabbana-14-40","n":28,"surah":14,"ayah":40,"part":"","arabic":"رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ","fr":"Mon Seigneur, fais de moi un assidu de la prière, ainsi qu’une partie de ma descendance. Notre Seigneur, accepte mon invocation.","en":"My Lord, make me an establisher of prayer, and some of my descendants too. Our Lord, accept my supplication."},
  {"id":"rabbana-14-41","n":29,"surah":14,"ayah":41,"part":"","arabic":"رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ","fr":"Notre Seigneur, pardonne-moi, ainsi qu’à mes parents et aux croyants, le jour où le compte sera établi.","en":"Our Lord, forgive me, my parents and the believers on the Day when the account is established."},
  {"id":"rabbana-18-10","n":30,"surah":18,"ayah":10,"part":"","arabic":"رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةًۭ وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًۭا","fr":"Notre Seigneur, accorde-nous de Ta part une miséricorde et facilite-nous la bonne direction dans notre affaire.","en":"Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair."},
  {"id":"rabbana-23-109","n":31,"surah":23,"ayah":109,"part":"","arabic":"رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ","fr":"Notre Seigneur, nous avons cru : pardonne-nous et fais-nous miséricorde, car Tu es le meilleur des miséricordieux.","en":"Our Lord, we have believed: forgive us and have mercy on us, for You are the best of the merciful."},
  {"id":"rabbana-25-65","n":32,"surah":25,"ayah":65,"part":"","arabic":"رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا","fr":"Notre Seigneur, détourne de nous le châtiment de l’Enfer, car son châtiment est permanent.","en":"Our Lord, turn away from us the punishment of Hell; its punishment is everlasting."},
  {"id":"rabbana-25-74","n":33,"surah":25,"ayah":74,"part":"","arabic":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","fr":"Notre Seigneur, fais que nos épouses et nos descendants soient la joie de nos yeux, et fais de nous un modèle pour les pieux.","en":"Our Lord, make our spouses and our children a joy to our eyes, and make us a leader for the righteous."},
  {"id":"rabbana-40-7","n":34,"surah":40,"ayah":7,"part":"","arabic":"رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍۢ رَّحْمَةًۭ وَعِلْمًۭا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ","fr":"Notre Seigneur, Tu embrasses toute chose de miséricorde et de science : pardonne à ceux qui se repentent et suivent Ta voie, et protège-les du châtiment de la Fournaise.","en":"Our Lord, You encompass all things in mercy and knowledge: forgive those who repent and follow Your way, and protect them from the punishment of the Blaze."},
  {"id":"rabbana-40-8","n":35,"surah":40,"ayah":8,"part":"","arabic":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fr":"Notre Seigneur, fais-les entrer aux jardins d’Éden que Tu leur as promis, ainsi que ceux qui ont été vertueux parmi leurs parents, leurs épouses et leurs descendants. Tu es le Puissant, le Sage.","en":"Our Lord, admit them to the gardens of Eden that You promised them, and the righteous among their parents, spouses and descendants. You are the Almighty, the Wise."},
  {"id":"rabbana-44-12","n":36,"surah":44,"ayah":12,"part":"","arabic":"رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ","fr":"Notre Seigneur, écarte de nous le châtiment ; nous sommes croyants.","en":"Our Lord, remove the punishment from us; we are believers."},
  {"id":"rabbana-59-10","n":37,"surah":59,"ayah":10,"part":"","arabic":"رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّۭا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌۭ رَّحِيمٌ","fr":"Notre Seigneur, pardonne-nous ainsi qu’à nos frères qui nous ont devancés dans la foi, et ne mets dans nos cœurs aucune rancœur envers ceux qui ont cru. Notre Seigneur, Tu es Compatissant et Miséricordieux.","en":"Our Lord, forgive us and our brothers who preceded us in faith, and do not put in our hearts any resentment toward those who believe. Our Lord, You are Kind and Merciful."},
  {"id":"rabbana-60-4","n":38,"surah":60,"ayah":4,"part":"","arabic":"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ","fr":"Notre Seigneur, c’est en Toi que nous plaçons notre confiance, vers Toi nous revenons repentants, et c’est vers Toi que sera le retour.","en":"Our Lord, in You we place our trust, to You we turn in repentance, and to You is the final return."},
  {"id":"rabbana-60-5","n":39,"surah":60,"ayah":5,"part":"","arabic":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fr":"Notre Seigneur, ne fais pas de nous une épreuve pour ceux qui ont mécru, et pardonne-nous, notre Seigneur. Tu es le Puissant, le Sage.","en":"Our Lord, do not make us a trial for those who disbelieve, and forgive us, our Lord. You are the Almighty, the Wise."},
  {"id":"rabbana-66-8","n":40,"surah":66,"ayah":8,"part":"","arabic":"رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","fr":"Notre Seigneur, parfais pour nous notre lumière et pardonne-nous. Tu es capable de toute chose.","en":"Our Lord, perfect our light for us and forgive us. You have power over all things."}
];

